-- Safe to run more than once: the deploy applies this file on every deploy (the production
-- database has no Prisma migration history), so the table is only created if it's missing and
-- the seed rows only go in if they aren't there yet. Edits made on /manage are never overwritten.

-- CreateTable
CREATE TABLE IF NOT EXISTS "site_content" (
    "kind" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "data" JSONB NOT NULL DEFAULT '{}',
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "isPublished" BOOLEAN NOT NULL DEFAULT true,
    "updatedByName" TEXT NOT NULL DEFAULT '',
    "updatedByEmail" TEXT NOT NULL DEFAULT '',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "site_content_pkey" PRIMARY KEY ("kind","slug")
);

-- The content that used to be typed into the frontend's data files, moved here as it was.

ON CONFLICT ("kind","slug") DO NOTHING;

ON CONFLICT ("kind","slug") DO NOTHING;

ON CONFLICT ("kind","slug") DO NOTHING;

ON CONFLICT ("kind","slug") DO NOTHING;

ON CONFLICT ("kind","slug") DO NOTHING;
